const lazyVideoObserver=new IntersectionObserver(e=>{for(const t of e)if(t.isIntersecting){const e=t.target,o=e.getAttribute("data-original-poster");o&&e.setAttribute("poster",o),e.hasAttribute("data-original-autoplay")&&e.setAttribute("autoplay","autoplay");const r=e.getAttribute("data-original-preload");r&&("default"===r?e.removeAttribute("preload"):e.setAttribute("preload",r)),lazyVideoObserver.unobserve(e)}},{rootMargin:"100% 0% 100% 0%",threshold:0}),videos=document.querySelectorAll("video.od-lazy-video");for(const e of videos)lazyVideoObserver.observe(e);